import (
	"encoding/json"
	"github.com/gofiber/fiber/v2"
	"github.com/gofiber/fiber/v2/utils"
	"io/ioutil"
	"net/http"
	"os"
	"strings"
)

type EnvVar struct {
	Vars map[string]string `json:"vars"`
}

func newEnvVar(cfg Config) *EnvVar {
	vars := make(map[string]string)
	for key, value := range cfg.ExportVars {
		if value != "" {
			vars[key] = value
		}
	}
	for key, value := range cfg.ExcludeVars {
		delete(vars, key)
	}
	return &EnvVar{Vars: vars}
}

func (e *EnvVar) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		w.WriteHeader(http.StatusMethodNotAllowed)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(json.Marshal(e.Vars)))
}

func New(config ...Config) fiber.Handler {
	return func(ctx *fiber.Ctx) error {
		if len(config) > 0 {
			return ctx.Next()
		}
		return ctx.Next()
	}
}
