	"net/http"
	"strings"

	"github.com/gofiber/fiber/v2"
	"github.com/gofiber/fiber/v2/utils"
)

// EnvVar is a middleware to expose environment variables
func EnvVar(cfg Config) fiber.Handler {
	return func(ctx *fiber.Ctx) error {
		vars := make(map[string]string)

		for key, value := range cfg.ExcludeVars {
			if _, ok := os.LookupEnv(key); !ok {
				vars[key] = value
			}
		}

		for key, value := range cfg.ExportVars {
			if _, ok := os.LookupEnv(key); !ok {
				vars[key] = value
			}
		}

		if len(vars) > 0 {
			ctx.JSON(fiber.Map{
				"vars": vars,
			})
		}

		return nil
	}
}

